const rows = $input.all().map(item => item.json);
const source = $('Edit Fields').first().json;
const mensaje = String(source.mensaje || '').trim();
const leadId = String(source.lead_id || '');
const tg = source.message || source.body?.message || {};
const chatId = tg.chat?.id || null;
const canal = chatId ? 'telegram' : 'webhook';
const sheetOk = rows.length > 0 && !rows.some(row => row.error || row.errorMessage || row.statusCode >= 400);
const valid = Boolean(mensaje && leadId && sheetOk);
const normal = mensaje.toLowerCase();
const propiedad = /(departamento|casa|ph|local|terreno|oficina)/.test(normal);
const zona = /(caballito|palermo|belgrano|recoleta|zona|barrio)/.test(normal);
const presupuesto = /(?:presupuesto|usd|us\$|d[oó]lares|\$)\s*[:=]?\s*\d|\d[\d.,]*\s*(?:usd|d[oó]lares)/i.test(normal);
const completos = propiedad && zona && presupuesto;
const fallback = {clasificacion:'revision_humana',accion:'revision_humana',mensaje: sheetOk ? 'No recibí una consulta válida. Por favor escribí tu mensaje.' : 'No pude procesar la consulta en este momento. Requiere revisión humana.',confianza:0};
return [{json:{valid,sheet_ok:sheetOk,lead_id:leadId,session_id:leadId,canal,chat_id:chatId,mensaje,datos_completos:completos,accion_sugerida:completos?'enviar_opciones':'pedir_datos',output:JSON.stringify(fallback)}}];

const input = $input.first().json;
let parsed;
try { parsed = typeof input.output === 'string' ? JSON.parse(input.output) : input.output; } catch { parsed = null; }
const clases = ['caliente','tibio','frio','revision_humana'];
const acciones = ['contactar_agente','enviar_opciones','pedir_datos','revision_humana'];
const mensaje = typeof parsed?.mensaje === 'string' ? parsed.mensaje.trim() : '';
const valido = parsed && clases.includes(parsed.clasificacion) && acciones.includes(parsed.accion) && mensaje.length > 0 && typeof parsed.confianza === 'number' && parsed.confianza >= 0 && parsed.confianza <= 1;
const promete = /confirmad[oa]s? (la )?visita|visita confirmada|disponibilidad confirmada|te (las |los )?(enviaré|enviaremos|mandaremos)|te contactaremos|se pondrá en contacto|estamos seleccionando|estoy preparando|he derivado|hemos derivado|ya (derivé|derivamos|avisamos|contactamos)/i.test(mensaje);
const final = valido && !promete ? parsed : {clasificacion:'revision_humana',accion:'revision_humana',mensaje:'La consulta requiere revisión humana. No puedo confirmar información adicional por este medio.',confianza:0.5};
const source = $('Edit Fields').first().json;
const tg = source.message || source.body?.message || {};
const chatId = tg.chat?.id || null;
const leadId = source.lead_id || 'demo-lead-001';
return [{json:{output:JSON.stringify(final,null,2),canal:chatId?'telegram':'webhook',chat_id:chatId,session_id:chatId?'telegram:'+chatId:leadId,remitente_id:tg.from?.id || leadId}}];
